get_pip_packages' second return value can be None: https://github.com/pytorch/pytorch/blob/269fa8028f68b29176e21886108634f48b1eced7/torch/utils/collect_env.py#L437-L457                lightning-thunder/thunder/dynamo/utils.py                   Lines 788 to 802       in       b0d82d5                                                 def get_env() -> tuple[str, str]:                                               """Retrieve detailed environment information using `torch.utils.collect_env.get_pip_packages()`.                                               Additionally, include the installed versions of Thunder and NvFuser (if available via pip).                                               """                                                                                          from torch.utils.collect_env import run, get_pip_packages                                                                                          torch_env = "CUDA devices:
"                                               for i in range(torch.cuda.device_count()):                                                   torch_env += f"  {i}: {torch.cuda.get_device_name(i)}
"                                               torch_env += f"CUDA version: {torch.version.cuda}
"                                               _, packages = get_pip_packages(run)                                               torch_env += packages                                               _, thunder_packages = get_pip_packages(run, {"lightning-thunder", "nvfuser"})                                               return torch_env, thunder_packages
